#!/bin/bash
# Smoke tests 1b-5 for the Llama-3.1-8B-Instruct suite. Chained afterok on the
# prefetch job, since every stage past 1b needs the weights on disk.
#
# NOT generated by gen_simplex3.py: this runs once per new base model, before the
# suite is submitted, and is deliberately not part of the standing job graph.
# submit_all.sh does not reference it, and should not.
#
# --expect-lora-params is not passed: the count (13,631,488) lives in the
# LLAMA3_INSTRUCT profile, which is where a claim about a checkpoint belongs.
#
# The --output directory must exist BEFORE submitting this or 00_prefetch.sh.
# submit_all.sh mkdir -p's it, but both of these run ahead of submit_all by
# design, and SLURM fails a job whose output path does not resolve with exit 53
# and no log file at all -- which looks exactly like nothing having happened:
#
#   mkdir -p /weka/scratch/jhu/cpriebe1/MO/model-taxonomy/results/simplex3_llama3i/logs
#SBATCH --job-name=s3li_smoke
#SBATCH --partition=h200,h100,l40s,a100
#SBATCH --gres=gpu:1
#SBATCH --mem=80G
#SBATCH --cpus-per-task=8
#SBATCH --time=1:30:00
#SBATCH --output=/weka/scratch/jhu/cpriebe1/MO/model-taxonomy/results/simplex3_llama3i/logs/s3li_smoke-%j.out

set -euo pipefail

source "$(conda info --base)/etc/profile.d/conda.sh"
conda activate taxonomy-env
cd /weka/scratch/jhu/cpriebe1/MO/model-taxonomy

export TOKENIZERS_PARALLELISM=false
export HF_HOME=/weka/scratch/jhu/cpriebe1/MO/huggingface_cache
export HF_DATASETS_OFFLINE=1

nvidia-smi --query-gpu=name,memory.total --format=csv,noheader

python scripts/smoke_base_model.py experiments/simplex3_llama3i/train_shard0.yaml
